// Parsers for the reference catalogs in registry/catalogs/. They read the Markdown tables, so keep the
// table layouts stable (healthkit-types.md is generated by scripts/healthkit-catalog.py).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { ROOT } from './registry.mjs';

export const HEALTHKIT_CATALOG = join(ROOT, 'registry/catalogs/healthkit-types.md');
export const HEALTH_CONNECT_CATALOG = join(ROOT, 'registry/catalogs/health-connect.md');

function sections(markdown, level) {
  const marker = `${'#'.repeat(level)} `;
  const out = [];
  let current = null;
  for (const line of markdown.split('\n')) {
    if (line.startsWith(marker)) {
      current = { title: line.slice(marker.length).trim(), lines: [] };
      out.push(current);
    } else if (current) current.lines.push(line);
  }
  return out;
}

/** Data rows of the first Markdown table in `lines`, as arrays of trimmed cells. */
function tableRows(lines) {
  const rows = [];
  let started = false;
  for (const line of lines) {
    if (!line.startsWith('|')) {
      if (started) break;
      continue;
    }
    started = true;
    if (/^\|\s*-/.test(line)) continue;
    rows.push(line.split('|').slice(1, -1).map((cell) => cell.trim()));
  }
  return rows.slice(1); // drop the header row
}

const unquote = (cell) => cell.replace(/`/g, '').replace(/\*\*/g, '').trim();

const HK_PREFIXES = {
  'Quantity types': 'HKQuantityTypeIdentifier',
  'Category types': 'HKCategoryTypeIdentifier',
  'Characteristic types': 'HKCharacteristicTypeIdentifier',
  'Correlation types': 'HKCorrelationTypeIdentifier',
  'Document types': 'HKDocumentTypeIdentifier',
  'Scored assessment types': 'HKScoredAssessmentTypeIdentifier',
};

/**
 * Every HealthKit identifier in registry/catalogs/healthkit-types.md:
 * `{ identifier, section, group, ios, notes, deprecated }`. "Other sample types" are taken from the
 * "Special object types" table instead, which has their full identifiers.
 */
export function healthKitIdentifiers(path = HEALTHKIT_CATALOG) {
  const out = [];
  for (const { title, lines } of sections(readFileSync(path, 'utf8'), 2)) {
    const name = title.replace(/\s*\(.*$/, '');
    const prefix = HK_PREFIXES[name];
    if (prefix) {
      for (const [group, ident, ios, notes = ''] of tableRows(lines)) {
        out.push({
          identifier: prefix + unquote(ident),
          section: name,
          group,
          ios,
          notes,
          deprecated: /deprecated/i.test(notes),
        });
      }
    } else if (name.startsWith('Special object types')) {
      for (const [ident, ios, notes = ''] of tableRows(lines)) {
        out.push({ identifier: unquote(ident), section: 'Special object types', group: '', ios, notes, deprecated: false });
      }
    }
  }
  return out;
}

/** HealthKit category value enums: `{ HKCategoryValueSeverity: { Unspecified: 0, … } }`. */
export function healthKitEnums(path = HEALTHKIT_CATALOG) {
  const enums = {};
  const section = sections(readFileSync(path, 'utf8'), 2).find((s) => s.title.startsWith('Category value enums'));
  for (const [name, , cases] of tableRows(section?.lines ?? [])) {
    enums[unquote(name)] = Object.fromEntries(
      [...cases.matchAll(/`(\w+)`=(\d+)/g)].map(([, caseName, raw]) => [caseName, Number(raw)]),
    );
  }
  return enums;
}

/**
 * Every Health Connect record in registry/catalogs/health-connect.md: the Jetpack catalog table (§E)
 * plus the framework-only records (§C2). `{ record, kind, gate, frameworkOnly }`.
 */
export function healthConnectRecords(path = HEALTH_CONNECT_CATALOG) {
  const markdown = readFileSync(path, 'utf8');
  const out = [];
  const catalog = sections(markdown, 2).find((s) => s.title.includes('Health Connect full catalog'));
  for (const [name, kind, , , , gate = ''] of tableRows(catalog?.lines ?? [])) {
    out.push({ record: `${unquote(name)}Record`, kind, gate: unquote(gate), frameworkOnly: false });
  }
  const c2 = sections(markdown, 3).find((s) => s.title.startsWith('C2.'));
  const framework = (c2?.lines ?? []).join('\n').split(/\*\*Framework-only/)[1] ?? '';
  for (const [, record, note] of framework.matchAll(/^- `(\w+Record)`: (.*)$/gm)) {
    if (!out.some((r) => r.record === record)) {
      out.push({ record, kind: '', gate: unquote(note.split('. ')[0]), frameworkOnly: true });
    }
  }
  return out;
}

export const WORKOUT_CATALOG = join(ROOT, 'registry/catalogs/workout-activity-types.md');

/**
 * registry/catalogs/workout-activity-types.md (scripts/workout-catalog.mjs): HealthKit activity cases
 * `{ name, raw, ios, note }` and Health Connect exercise / segment constants `{ name, raw }`.
 */
export function workoutCatalog(path = WORKOUT_CATALOG) {
  const byTitle = Object.fromEntries(sections(readFileSync(path, 'utf8'), 2).map((s) => [s.title, s.lines]));
  const constants = (title) => tableRows(byTitle[title]).map(([name, raw]) => ({ name: unquote(name), raw: Number(raw) }));
  return {
    healthKit: tableRows(byTitle.HKWorkoutActivityType).map(([name, raw, ios, note = '']) => ({
      name: unquote(name),
      raw: Number(raw),
      ios,
      note,
    })),
    exerciseTypes: constants('ExerciseSessionRecord exercise types'),
    segmentTypes: constants('ExerciseSegment segment types'),
  };
}
